CREATE TRIGGER update_auth_user_ftux
AFTER
UPDATE
  OF show_ftux ON public.users FOR EACH ROW EXECUTE FUNCTION update_auth_user_ftux();

CREATE TRIGGER update_auth_user_terms
AFTER
UPDATE
  OF accepted_terms ON public.users FOR EACH ROW EXECUTE FUNCTION update_auth_user_terms();
